"""Campos de cancelación (motivo, fecha, quién) en los documentos de finanzas y
alta de los permisos de cancelación por tipo. Los roles que ya tenían
``E-FIN-FACTURAS`` reciben los cuatro para no cambiar a nadie: el admin los
reparte después. El catálogo vive solo en la BD. Reverso: no borra permisos."""
# Generated by Django 6.0.6 on 2026-11-24 17:34

import django.db.models.deletion
from django.conf import settings
from django.db import migrations, models


PERMISOS = {
    "CANCELAR-FIN-POLIZAS": "Cancelar pólizas contables",
    "CANCELAR-FIN-COBROS": "Cancelar cobros y su REP",
    "CANCELAR-FIN-PAGOS": "Cancelar pagos y facturas de proveedor",
    "CANCELAR-FIN-BANCOS": "Cancelar movimientos bancarios y conciliaciones",
}


def crear_permisos(apps, schema_editor):
    Permiso = apps.get_model("seguridad", "Permiso")
    RolPermiso = apps.get_model("seguridad", "RolPermiso")
    roles = list(RolPermiso.objects.filter(permiso__clave="E-FIN-FACTURAS").values_list("rol_id", flat=True).distinct())
    for clave, nombre in PERMISOS.items():
        permiso, _ = Permiso.objects.get_or_create(
            clave=clave, defaults={"nombre": nombre, "descripcion": nombre, "modulo": "FINANZAS"},
        )
        for rol_id in roles:
            RolPermiso.objects.get_or_create(rol_id=rol_id, permiso=permiso)


